package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.worldgen.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=KelMagic.MODID)public final class QaLocate {
 static volatile boolean done;static boolean started;static int ticks;static long begin;static net.minecraft.commands.CommandSourceStack source;
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.locateQA")||done||e.getServer().getPlayerList().getPlayers().isEmpty())return;if(!started){started=true;source=e.getServer().createCommandSourceStack().withPosition(new net.minecraft.world.phys.Vec3(20000,64,20000));begin=System.nanoTime();e.getServer().getCommands().performPrefixedCommand(source,"locate structure kelmagic:archive");long ns=System.nanoTime()-begin;if(ArchiveSearch.pending()!=1||ns>500_000_000)throw new IllegalStateException("Search did not queue promptly: "+ns);System.out.println("ARCHIVE_ASYNC_COMMAND_QUEUED_MS="+ns/1000000);return;}ticks++;if(ArchiveSearch.pending()==0){done=true;System.out.println("ARCHIVE_ASYNC_TICKS_WHILE_SEARCHING="+ticks+" elapsed_ms="+(System.nanoTime()-begin)/1000000);if(ticks<2)throw new IllegalStateException("Search did not yield across ticks");}}
}
